   {aiQuotes.length>0&&<details style={{marginTop:12}}><summary>گزیدهٔ کمکی AI؛ نیازمند بررسی</summary><p className="muted">گزینش ماشینی عبارت‌های منبع است؛ صلاحیت، هویت یا شرایط جدیدی تأیید نمی‌کند.</p>{aiQuotes.map((quote,index)=><blockquote dir="auto" key={index} style={{overflowWrap:'anywhere'}}><MixedText>{quote}</MixedText></blockquote>)}{safeLink(enrichment.sourceURL)&&<a href={safeLink(enrichment.sourceURL)} target="_blank" rel="noreferrer">منبع گزیده‌ها</a>}<p className="muted">زمان: {date(enrichment.ai.readAt)}</p></details>}
